  /** Each grade's own rates (not its ancestors'), the undated one first and then by from-date. */
  protected readonly sorted = computed(() =>
    this.rates().filter((r) => (r.level ?? 0) === 0).sort(
      (a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? ''),
    ),
  );
  /** Each grade's rate in force on the sheet's today. */
  protected readonly current = computed(() => {
    const today = this.session.today();
    return new Map(GRADES.map((g) => [g, pctOn(this.rates(), g, today)]));
  });
  /** Each month (yyyy-mm) of the sheet's today's calendar year; none without a today. */
  protected readonly calendarMonths = computed(() => {
    const year = this.session.today()?.slice(0, 4);
    if (!year) return [];
    return Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`);
  });
  /** Each grade's rate in force on the first day of each calendar month, keyed grade-yyyy-mm. */
  protected readonly calendar = computed(() => {
    const rates = this.rates();
    const out = new Map<string, string | undefined>();
    for (const g of GRADES) {
      for (const m of this.calendarMonths()) out.set(`${g}-${m}`, pctOn(rates, g, `${m}-01`));
    }
    return out;
  });
  protected readonly gradeInput = signal<string>('A');
  protected readonly pctInput = signal('');
  protected readonly fromInput = signal('');
  protected readonly toInput = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly importText = signal('');
  /** How many rates the last import set; cleared while the next one runs. */
  protected readonly importSet = signal<number | null>(null);
  protected readonly importError = signal<string | null>(null);
  /** Whether an import is waiting for its answer: a second one meanwhile is ignored. */
  private importing = false;
  protected readonly previewGrade = signal<string>('A');
  protected readonly previewPct = signal('');
  /** The last preview's answer: how many claims would change and the sum of the differences. */
  protected readonly previewResult = signal<{ count: number; diff: string } | null>(null);
  protected readonly previewError = signal<string | null>(null);
  /** Counts each preview pressed, so only the latest one's answer is shown. */
  private previewRun = 0;
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;

  constructor() {
    // Re-read the sheet's rates from the store every time a sheet is loaded.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.rates.set([]);
      this.gradeInput.set('A');
      this.pctInput.set('');
      this.fromInput.set('');
      this.toInput.set('');
      this.error.set(null);
      this.importText.set('');
      this.importSet.set(null);
      this.importError.set(null);
      this.previewGrade.set('A');
      this.previewPct.set('');
      this.clearPreview();
      if (sheet) {
        void this.fetch(sheet);
      }
    });
    // Re-read them when the sheet's parent changes: its ancestors' rates stand in for missing ones.
    let parentSeen: string | null = null;
    effect(() => {
      const parent = this.session.parent();
      const sheet = untracked(() => this.session.sheet());
      if (parentSeen !== null && parent !== parentSeen && sheet) void this.fetch(sheet);
      parentSeen = parent;
    });
  }

  private async fetch(sheet: string): Promise<void> {
    try {
      const list = await firstValueFrom(this.http.post<Rate[]>('/api/rates/list', { sheet }));
      if (this.session.sheet() === sheet) this.rates.set(list);
    } catch {
      this.error.set('Could not read the rates on this sheet.');
    }
  }

  /** Set every pasted line's rate, or none when any line breaks the rate form's rules. */
  protected async importRates(event: Event): Promise<void> {
    event.preventDefault();
    if (this.importing) return;
    this.importSet.set(null);
    this.importError.set(null);
    const sheet = this.session.sheet();
    this.importing = true;
    try {
      const res = await firstValueFrom(
        this.http.post<{ set: number; rates: Rate[] }>('/api/rates/import', {
          sheet,
          user: this.session.user(),
          text: this.importText(),
        }),
      );
      if (!sheet || this.session.sheet() !== sheet) return;
      await this.fetch(sheet);
      this.importSet.set(res.set);
        this.rates = rates;
        this.rateLog = rateLog;
    }

    /** The sheet's id, then its parent's, and so on, up to {@link #LEVELS} levels up. */
    public List<String> lineage(String sheetId) {
        List<String> ids = new ArrayList<>();
        ids.add(sheetId);
        String at = sheetId;
        while (ids.size() <= LEVELS) {
            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
            if (parent == null || ids.contains(parent)) {
                break;
            }
            ids.add(parent);
            at = parent;
        }
        return ids;
    }

    /** Whether naming {@code parentId} as the sheet's parent would make the sheet its own ancestor. */
    public boolean wouldLoop(String sheetId, String parentId) {
        List<String> seen = new ArrayList<>();
        String at = parentId;
        while (at != null && !seen.contains(at)) {
            if (at.equals(sheetId)) {
                return true;
            }
            seen.add(at);
            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
        }
        return false;
    }

    /**
     * The rates of the sheet and of each ancestor, nearest first, as the store holds them now. When the
     * request is answered as of a date, only the sheet is restored as it stood then (see {@link AsOfFilter}),
     * so each ancestor's rates are those it had at the end of that date.
     */
    public List<List<Rate>> current(String sheetId) {
        Optional<LocalDate> asOf = AsOfFilter.current();
        List<String> ids = lineage(sheetId);
        List<List<Rate>> chain = new ArrayList<>();
        chain.add(rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId));
        for (String id : ids.subList(1, ids.size())) {
            chain.add(asOf.isPresent() ? rateLog.asOf(id, asOf.get()) : rates.findBySheetIdOrderByGradeAscFromDateAsc(id));
        }
        return chain;
    }

    /** The rates of the sheet and of each ancestor, nearest first, as they stood at the end of a day. */
    public List<List<Rate>> asOf(String sheetId, LocalDate day) {
        return lineage(sheetId).stream().map(id -> rateLog.asOf(id, day)).toList();
    }

    /**
     * The grade's rate in force on a date: the sheet's own (as {@link RateRepository#inForce} picks it),
     * else the nearest ancestor's; empty when none has one.
     */
    public static Optional<Rate> inForce(List<List<Rate>> chain, String grade, LocalDate date) {
        for (List<Rate> level : chain) {
            Optional<Rate> rate = RateRepository.inForce(level, grade, date);
            if (rate.isPresent()) {
                return rate;
            }
        }
        return Optional.empty();
    }

    /**
     * The grade's rate in force on a claim's date among the rates that apply to the claim (see
     * {@link Rate#appliesTo}): the sheet's own, else the nearest ancestor's; empty when none has one.
     */
    public static Optional<Rate> inForce(List<List<Rate>> chain, String grade, Claim claim) {
        for (List<Rate> level : chain) {
            Optional<Rate> rate = RateRepository.inForce(level, grade, claim);
            if (rate.isPresent()) {
                return rate;
            }
        }
        return Optional.empty();
    }

    /** The grade's rate in force for a claim on the sheet or, failing that, its nearest ancestor. */
    public Optional<Rate> findInForce(String sheetId, String grade, Claim claim) {
        return inForce(current(sheetId), grade, claim);
    }

    /** The grade's rate in force on a date on the sheet or, failing that, its nearest ancestor. */
    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(current(sheetId), grade, date);
    }
}

