        this.service = service;
        this.roles = roles;
        this.clones = clones;
        this.locales = locales;
    }

    @PostMapping("/signin")
    public SignInResponse signIn(@Valid @RequestBody SignInRequest req) {
        String name = req.name().trim();
        return new SignInResponse(name, locales.localeOf(name));
    }

